using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LighFight.Runtime;
// Review-only material instances and original-weight witness. Never edits source mesh/material/prefab.
public static class UniqueDanceSailorCollarDiagnostic {
 const string Folder="Assets/UniqueDancesReview/Fighter-9",Output="../art/source/unique-dances-20261018/audit/sailor-collar-material-diagnostic";
 public static void Run(){Directory.CreateDirectory(Output);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var original=AssetDatabase.LoadAssetAtPath<GameContent>("Assets/LighFight/Content/GameContent.asset").fighters[9];var bind=(GameObject)PrefabUtility.InstantiatePrefab(original);var bindSkin=bind.GetComponentInChildren<SkinnedMeshRenderer>();foreach(var b in bind.GetComponentsInChildren<Behaviour>())b.enabled=false;var animator=bind.GetComponentInChildren<Animator>();Vector3 neck=animator.GetBoneTransform(HumanBodyBones.Neck).position;var bindOracle=new OriginalSkinWorldOracle(bindSkin);bindOracle.Refresh();var vertices=bindSkin.sharedMesh.vertices;var weights=bindSkin.sharedMesh.boneWeights;var chosen=new List<int>();var used=new HashSet<int>(bindSkin.sharedMesh.triangles);for(int i=0;i<vertices.Length;i++){var p=bindOracle.VertexWorld(i);if(used.Contains(i)&&Mathf.Abs(p.x-neck.x)<.28f&&p.y>neck.y-.20f&&p.y<neck.y+.07f&&Mathf.Abs(p.z-neck.z)<.23f)chosen.Add(i);}var rows=new List<string>{"pose,originalVertex,worldX,worldY,worldZ,bone0,weight0,bone1,weight1,bone2,weight2,bone3,weight3"};Append("original-prefab-guard",bindOracle,bindSkin,chosen,weights,rows);bind.SetActive(false);
 var camera=new GameObject("CollarDiagnosticCamera").AddComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.15f,.17f,.2f);RenderSettings.ambientLight=new Color(.6f,.6f,.6f);var key=new GameObject("CollarDiagnosticKey").AddComponent<Light>();key.type=LightType.Directional;key.intensity=1.1f;key.transform.rotation=Quaternion.Euler(32,-35,0);var provenance=new List<string>{"Original mesh="+AssetDatabase.GetAssetPath(bindSkin.sharedMesh),"Original rendered vertices="+bindOracle.RenderedVertexCount,"Medial collar original-vertex witness count="+chosen.Count,"Selection: approved serialized guard world |x-neck.x|<.28m, neck.y-.20<y<neck.y+.07m, |z-neck.z|<.23m; all indexed original vertices, unchanged weights."};
 foreach(bool corrected in new[]{false,true}){var actor=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/Review.exact-generic-anatomic-v3"+(corrected?".support":"")+".prefab"));foreach(var b in actor.GetComponentsInChildren<Behaviour>())b.enabled=false;var driver=actor.GetComponent<ExactGenericDanceRetarget>();var skin=actor.GetComponentInChildren<SkinnedMeshRenderer>();var sourceMaterials=skin.sharedMaterials;var noNormal=sourceMaterials.Select(m=>new Material(m)).ToArray();foreach(var m in noNormal){foreach(var n in new[]{"_BumpMap","_NormalMap","_DetailNormalMap"})if(m.HasProperty(n))m.SetTexture(n,null);m.DisableKeyword("_NORMALMAP");m.DisableKeyword("_DETAIL_MULX2");}var clay=sourceMaterials.Select(m=>new Material(Shader.Find("Standard")){color=new Color(.62f,.62f,.62f)}).ToArray();foreach(var m in clay){m.SetFloat("_Glossiness",.12f);m.SetFloat("_Metallic",0);}foreach(var m in sourceMaterials)provenance.Add("Source material="+AssetDatabase.GetAssetPath(m)+" shader="+m.shader.name+" textures="+string.Join("|",m.GetTexturePropertyNames().Select(n=>n+":"+AssetDatabase.GetAssetPath(m.GetTexture(n)))));
 if(!corrected){actor.SetActive(false);bind.SetActive(true);var saved=bindSkin.sharedMaterials;foreach(string mode in new[]{"atlas","atlas-no-normal","flat-clay"}){bindSkin.sharedMaterials=mode=="atlas"?sourceMaterials:mode=="atlas-no-normal"?noNormal:clay;foreach(string side in new[]{"front","back","raised-oblique"}){camera.orthographicSize=.24f;Vector3 direction=side=="front"?Vector3.forward:side=="back"?Vector3.back:new Vector3(-.65f,0,1).normalized;Vector3 center=neck-Vector3.up*.055f;camera.transform.position=center+direction*4;camera.transform.LookAt(center);Save(camera,"original-prefab-guard-"+mode+"-"+side);}}bindSkin.sharedMaterials=saved;bind.SetActive(false);actor.SetActive(true);}
 var oracle=new OriginalSkinWorldOracle(skin);foreach(float phase in new[]{0f,.25f,.5f,.75f,1f}){driver.EvaluateForReview(phase*driver.source.duration);actor.GetComponent<CandidateFootGrounding>().ApplyForReview();oracle.Refresh();string label=(corrected?"c1":"base")+"-phase-"+Mathf.RoundToInt(phase*100);Append(label,oracle,skin,chosen,weights,rows);Vector3 center=driver.targetMapped[4].position-Vector3.up*.055f;foreach(string mode in new[]{"atlas","atlas-no-normal","flat-clay"}){skin.sharedMaterials=mode=="atlas"?sourceMaterials:mode=="atlas-no-normal"?noNormal:clay;foreach(string side in new[]{"front","back","raised-oblique"}){camera.orthographicSize=.24f;Vector3 direction=side=="front"?Vector3.forward:side=="back"?Vector3.back:new Vector3(-.65f,0,1).normalized;camera.transform.position=center+direction*4;camera.transform.LookAt(center);Save(camera,label+"-"+mode+"-"+side);}}}skin.sharedMaterials=sourceMaterials;foreach(var m in noNormal.Concat(clay))UnityEngine.Object.DestroyImmediate(m);Destroy(actor);}
 File.WriteAllLines(Output+"/original-medial-collar-weights-and-poses.csv",rows);File.WriteAllLines(Output+"/provenance.txt",provenance.Distinct());Destroy(bind);UnityEngine.Object.DestroyImmediate(camera.gameObject);UnityEngine.Object.DestroyImmediate(key.gameObject);Debug.Log("AGENT_RESULT collar original-weight/material diagnostic retained; no geometry edits or acceptance claim");}
 static void Append(string pose,OriginalSkinWorldOracle oracle,SkinnedMeshRenderer skin,List<int> chosen,BoneWeight[] weights,List<string> rows){foreach(int i in chosen){var p=oracle.VertexWorld(i);var w=weights[i];rows.Add(pose+","+i+","+p.x+","+p.y+","+p.z+","+skin.bones[w.boneIndex0].name+","+w.weight0+","+skin.bones[w.boneIndex1].name+","+w.weight1+","+skin.bones[w.boneIndex2].name+","+w.weight2+","+skin.bones[w.boneIndex3].name+","+w.weight3);}}
 static void Save(Camera c,string name){var rt=RenderTexture.GetTemporary(960,720,24);c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(960,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,960,720),0,0);t.Apply();File.WriteAllBytes(Output+"/"+name+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);RenderTexture.active=old;c.targetTexture=null;RenderTexture.ReleaseTemporary(rt);}
 static void Destroy(GameObject a){if(!a)return;foreach(var b in a.GetComponents<MonoBehaviour>())if(b is IActorCurveWarmup w)w.Dispose();UnityEngine.Object.DestroyImmediate(a);}
}
